script:
frappe.ui.form.on("Sales Invoice", {
    taxes_add(frm) {
        enforce_single_tax_row(frm);
    },
    validate(frm) {
        enforce_single_tax_row(frm);
    }
});

function enforce_single_tax_row(frm) {
    let taxes = frm.doc.taxes || [];

    if (taxes.length > 1) {
        // Keep the first row, remove the rest
        let rows_to_remove = taxes.slice(1);

        rows_to_remove.forEach(row => {
            frm.get_field("taxes").grid.grid_rows_by_docname[row.name].remove();
        });

        frappe.msgprint("Only one Tax and Charge row is allowed. Extra rows were removed.");
    }
}
